llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Glafenine, a 7-chloro-4-aminoquinoline analogue, has an absolute oral bioavailability of approximately 33% in healthy volunteers, which is above the 20% threshold and supports high bioavailability for the shared quinoline core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Piperaquine, a bis-4-aminoquinoline antimalarial, shows a median oral bioavailability of 0.77 in humans, strongly supporting high oral bioavailability for quinoline-based antimalarials.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Adinazolam has an absolute oral bioavailability of about 39% in healthy volunteers, providing additional evidence that molecules with similar moderate lipophilicity and basic amine character can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Chlorpheniramine oral bioavailability ranges from 25% to 50% in humans, supporting high bioavailability at the F ≥ 20% threshold despite its basic amine and moderate lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Clomipramine has an absolute oral bioavailability of approximately 48% in healthy volunteers, supporting high oral bioavailability for a lipophilic basic amine drug with first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Zotepine has a low absolute oral bioavailability of 7-13%, but its tricyclic antipsychotic scaffold and extensive first-pass metabolism are structurally distant from the query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pyronaridine is reported to have low oral bioavailability in humans, but the report is qualitative and the molecule is structurally more complex than the query, so this provides only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 7-chloro-4-aminoquinoline with a basic dimethylaminomethylbenzylamine side chain and favorable physicochemical properties. Most transferable experimental analogues, including glafenine (F~33%), piperaquine (F~77%), chlorpheniramine (25-50%), and clomipramine (~48%), show oral bioavailability above the 20% threshold. The only low-bioavailability analogues are structurally distant and their low values reflect scaffold-specific liabilities. Therefore, high oral bioavailability (F ≥ 20%) is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Morgan similarities to experimental analogues are modest (0.20-0.34), limiting quantitative transfer.",
    "No human PK data are available for a close 4-aminoquinoline with the exact dimethylaminomethylbenzyl side chain.",
    "Metabolic stability and first-pass extraction for this specific scaffold are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

